import type { Register, SessionMessage } from 'claude-code'

// /spinoff [--detach] [--no-group] <task>
//
// Answers its own command, so the big session's model never runs (no cache
// miss on its transcript). Haiku reads the transcript's tail and writes the
// brief; the app's own start_session tool starts the new session.
//
// By default the new session stays nested under this one, as the app draws a
// side session. A nested session reports back when its first turn ends, which
// would wake this session's model, so a prompt.submit hook drops that wake-up
// when it names only sessions /spinoff started. --detach moves the new session
// to top level instead and files both under one custom sidebar group.

const TAIL_CHARS = 120_000 // ~30k tokens of recent transcript for Haiku
const PER_MESSAGE_CHARS = 4_000
const OPENING_CHARS = 6_000
const CHILDREN_KEY = 'children'
const MAX_CHILDREN = 200
const WAKE_TAG = '<side-sessions-event>'

export type SpinoffArgs = { task: string; detach: boolean; group: boolean }

export function parseArgs(raw: string): SpinoffArgs {
  let detach = false
  let group = true
  const words: string[] = []
  for (const word of raw.trim().split(/\s+/).filter(Boolean)) {
    if (word === '--detach') detach = true
    else if (word === '--no-group') group = false
    else if (word === '--nest') continue // the default now; still accepted
    else words.push(word)
  }
  return { task: words.join(' '), detach, group }
}

// A session /spinoff started nested, kept in the plugin's store so the
// wake-up hook knows it across hot reloads and restarts.
export type Child = { id: string; title: string }

const SESSION_IDS = /local_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g

// The children a side-sessions wake-up is about, or undefined when it should
// go through: not a wake-up, about no child we know, or about another session
// too. Matches by id, else by title, since the event's wording is the app's
// and not documented.
export function wakeChildren(text: string, children: readonly Child[]): Child[] | undefined {
  if (!text.includes(WAKE_TAG)) return undefined
  const ids = [...new Set(text.match(SESSION_IDS) ?? [])]
  if (ids.length > 0) {
    const known = ids.map(id => children.find(c => c.id === id))
    return known.every(c => c !== undefined) ? (known as Child[]) : undefined
  }
  const byTitle = children.filter(c => c.title && text.includes(c.title))
  return byTitle.length > 0 ? byTitle : undefined
}

const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n)} […]` : s)

function renderMessage(m: SessionMessage): string {
  const lines: string[] = []
  if (m.text.trim()) lines.push(`[${m.role}] ${clip(m.text.trim(), PER_MESSAGE_CHARS)}`)
  for (const use of m.toolUses) {
    const input = JSON.stringify(use.input)
    lines.push(`  → ${use.tool}(${clip(input, 300)})${use.isError ? ' [error]' : ''}`)
  }
  return lines.join('\n')
}

// The opening user prompt (the original goal) plus as much of the tail as fits.
export function renderTranscript(messages: readonly SessionMessage[]): string {
  const rendered = messages.map(renderMessage).filter(Boolean)
  if (rendered.length === 0) return ''
  const firstUser = messages.find(m => m.role === 'user' && m.text.trim())
  const opening = firstUser ? `[opening request] ${clip(firstUser.text.trim(), OPENING_CHARS)}` : ''

  const tail: string[] = []
  let size = 0
  for (const message of [...rendered].reverse()) {
    if (size + message.length > TAIL_CHARS) break
    tail.unshift(message)
    size += message.length
  }
  const skipped = rendered.length - tail.length
  return [opening, skipped > 0 ? `[… ${skipped} earlier messages omitted …]` : '', ...tail]
    .filter(Boolean)
    .join('\n\n')
}

export function parseBrief(reply: string, task: string): { title: string; background: string } {
  const match = reply.match(/^\s*TITLE:\s*(.+)\n([\s\S]*)$/)
  const title = clip((match?.[1] ?? task).trim(), 56).replace(/ \[…\]$/, '…')
  const background = (match?.[2] ?? reply).replace(/^\s*-{3,}\s*\n/, '').trim()
  return { title, background }
}

export function findSessionId(text: string): string | undefined {
  return text.match(/local_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/)?.[0]
}

const BRIEF_SYSTEM = `You write handoff briefs. A developer is starting a NEW Claude Code session with no memory of an earlier one, to do a follow-up task. From the earlier session's transcript, write what the new session needs and nothing else.

Reply in exactly this form:
TITLE: <under 50 characters naming the new task>
<the brief>

The brief, in plain markdown, under 600 words:
- Goal: what the earlier session was working toward.
- State: what was done and what was left, as of the transcript's end.
- Key facts: files, commands, decisions, constraints, gotchas the new task will need. Be specific: real paths and names.
- Open questions or loose ends relevant to the new task.
Leave out anything unrelated to the new task. Never invent details the transcript does not contain.`

const toolText = (r: unknown): string => {
  const res = r as { text?: string; deny?: string; isError?: boolean }
  if (res.deny) throw new Error(res.deny)
  if (res.isError) throw new Error(res.text ?? 'tool failed')
  return res.text ?? ''
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'spinoff',
      description: 'Start a fresh-context session for a follow-up task, briefed from this one by Haiku',
      argumentHint: '[--detach] [--no-group] <task>',
    })
    return next(e)
  })

  on('command.run', { command: 'spinoff' }, async ($, e) => {
    const args = parseArgs(e.args)
    if (!args.task) {
      return {
        text: 'Usage: /spinoff [--detach] [--no-group] <task for the new session>\nBy default the new session nests under this one; its report-back is dropped so this session stays asleep.\n--detach moves it to top level and files both sessions under a sidebar group (--no-group skips the group).',
      }
    }

    const call = async (tool: string, input: Record<string, unknown> = {}) =>
      toolText(await $.tool.call({ tool, ...input } as never))

    try {
      $.ui.status('spinoff: reading transcript…')
      // The app's id for this session (local_…), not the CLI's transcript id.
      const self = JSON.parse(await call('mcp__ccd_session_mgmt__get_session', { session_id: 'self' }))
      const parentId: string = self.sessionId
      const transcript = renderTranscript(await $.session.messages())
      if (!transcript) return { text: 'spinoff: this session has no transcript to brief from yet.' }

      $.ui.status('spinoff: Haiku is writing the brief…')
      const reply = await $.model.complete({
        model: 'haiku',
        system: BRIEF_SYSTEM,
        prompt: `New task for the new session:\n${args.task}\n\n<transcript>\n${transcript}\n</transcript>`,
        maxTokens: 2000,
        timeoutMs: 120_000,
      })
      if (!reply.isAnswered) return { text: `spinoff: Haiku gave no brief (${reply.reason}).` }
      const { title, background } = parseBrief(reply.text, args.task)
      const fullBackground = `${background}\n\n---\nThis brief was written by Haiku from the tail of session ${parentId}. For detail it lacks, search or export that session's transcript with the ccd_session_mgmt tools (search_session_transcripts, export_transcript) rather than guessing.`

      $.ui.status('spinoff: starting session…')
      const started = await call('mcp__ccd_session__start_session', {
        initiation: 'user_asked',
        context: 'fresh',
        title,
        prompt: args.task,
        background: fullBackground,
      })
      $.ui.log(`spinoff: start_session said: ${started}`, { to: 'debug' })
      const childId = findSessionId(started)
      if (!childId) return { text: `spinoff: started "${title}", but could not read its id:\n${started}` }

      const notes: string[] = []
      let nested = !args.detach
      if (args.detach) {
        try {
          await call('mcp__ccd_session_mgmt__detach_session', { session_id: childId })
        } catch (err) {
          nested = true
          notes.push(`could not detach it (${err}); it stays nested`)
        }
      }
      if (nested) {
        const children = ((await $.store.get(CHILDREN_KEY)) ?? []) as Child[]
        await $.store.set(CHILDREN_KEY, [...children, { id: childId, title }].slice(-MAX_CHILDREN))
        notes.push('nested under this session; its report-back will be dropped so this session stays asleep')
      }

      if (args.detach && args.group) {
        try {
          let groupId: string | undefined = self.group?.id
          let groupName: string | undefined = self.group?.name
          if (!groupId) {
            groupName = clip(String(self.title ?? 'Spinoffs'), 60).replace(/ \[…\]$/, '…')
            const created = await call('mcp__ccd_sidebar__create_group', { name: groupName })
            groupId = created.match(/cg-[0-9a-f-]+/)?.[0] ?? JSON.parse(created).id
          }
          const ids = self.group?.id ? [childId] : ['self', childId]
          await call('mcp__ccd_sidebar__move_sessions', { session_ids: ids, group_id: groupId })
          notes.push(`filed under the group "${groupName}"`)
        } catch (err) {
          notes.push(`could not group the sessions (${err})`)
        }
      }

      return {
        text: [`spinoff: started "${title}" (${childId}).`, ...notes.map(n => `- ${n}`)].join('\n'),
      }
    } catch (err) {
      return { text: `spinoff failed: ${err}` }
    } finally {
      $.ui.status(undefined)
    }
  })

  on('prompt.submit', async ($, e, next) => {
    if (!e.text.includes(WAKE_TAG)) return next(e)
    const children = ((await $.store.get(CHILDREN_KEY)) ?? []) as Child[]
    const woken = wakeChildren(e.text, children)
    const origin = e.origin?.kind ?? 'unknown'
    $.ui.log(`spinoff: side-sessions wake-up, origin ${JSON.stringify(e.origin)}:\n${e.text}`, { to: 'debug' })
    if (!woken) {
      $.ui.log(`spinoff: let a side-sessions wake-up through (origin: ${origin}); it names a session /spinoff did not start`)
      return next(e)
    }
    $.ui.log(`spinoff: dropped the wake-up from ${woken.map(c => `"${c.title}"`).join(', ')} (origin: ${origin})`)
    return { drop: 'spinoff: report-back from a spun-off session' }
  })
}

